import { createPlayerError } from "./errors.js";
import type {
  ChunkedSource,
  MediaKind,
  MediaProvider,
  NormalizedSource,
  PlayerSource,
  PlayerSourceInput,
} from "./types.js";

const VIDEO_EXTENSIONS = new Set(["mp4", "m4v", "webm", "ogv", "ogg", "mov", "mkv", "m3u8", "mpd"]);

const AUDIO_EXTENSIONS = new Set(["mp3", "m4a", "aac", "wav", "oga", "flac", "opus", "weba"]);

const IMAGE_EXTENSIONS = new Set([
  "jpg",
  "jpeg",
  "png",
  "gif",
  "webp",
  "avif",
  "svg",
  "bmp",
  "ico",
]);

const MIME_BY_EXTENSION: Readonly<Record<string, string>> = {
  mp4: "video/mp4",
  m4v: "video/mp4",
  webm: "video/webm",
  ogv: "video/ogg",
  ogg: "video/ogg",
  mov: "video/quicktime",
  mkv: "video/x-matroska",
  m3u8: "application/vnd.apple.mpegurl",
  mpd: "application/dash+xml",
  mp3: "audio/mpeg",
  m4a: "audio/mp4",
  aac: "audio/aac",
  wav: "audio/wav",
  oga: "audio/ogg",
  flac: "audio/flac",
  opus: "audio/opus",
  weba: "audio/webm",
  jpg: "image/jpeg",
  jpeg: "image/jpeg",
  png: "image/png",
  gif: "image/gif",
  webp: "image/webp",
  avif: "image/avif",
  svg: "image/svg+xml",
  bmp: "image/bmp",
  ico: "image/x-icon",
};

const objectIds = new WeakMap<object, number>();
let nextObjectId = 1;

function baseUrl(): string {
  if (typeof document !== "undefined" && typeof document.baseURI === "string") {
    return document.baseURI;
  }

  if (typeof location !== "undefined" && typeof location.href === "string") {
    return location.href;
  }

  return "http://localhost/";
}

function toUrl(value: string): URL {
  try {
    return new URL(value, baseUrl());
  } catch (cause) {
    throw createPlayerError("The media source is not a valid URL.", {
      code: "invalid-argument",
      cause,
      details: { source: value },
    });
  }
}

/** Returns the lowercase extension of a URL path, without the dot. */
export function extensionOf(pathname: string): string | null {
  const lastSegment = pathname.split("/").pop() ?? "";
  const dot = lastSegment.lastIndexOf(".");

  if (dot < 1 || dot === lastSegment.length - 1) {
    return null;
  }

  return lastSegment.slice(dot + 1).toLowerCase();
}

/** Infers a media kind from an extension, MIME type and URL. */
export function detectMediaKind(
  extension: string | null,
  mimeType: string | null,
  url: URL,
): MediaKind {
  if (isYouTubeHost(url.hostname) || isVimeoHost(url.hostname)) {
    return "embed";
  }

  if (mimeType !== null) {
    if (mimeType.startsWith("image/")) {
      return "image";
    }

    if (mimeType.startsWith("audio/")) {
      return "audio";
    }

    if (
      mimeType.startsWith("video/") ||
      mimeType.includes("mpegurl") ||
      mimeType.includes("dash")
    ) {
      return "video";
    }
  }

  if (extension !== null) {
    if (IMAGE_EXTENSIONS.has(extension)) {
      return "image";
    }

    if (AUDIO_EXTENSIONS.has(extension)) {
      return "audio";
    }

    if (VIDEO_EXTENSIONS.has(extension)) {
      return "video";
    }
  }

  return "video";
}

/** Infers a MIME type from an extension. */
export function inferMimeType(extension: string | null): string | null {
  return extension === null ? null : (MIME_BY_EXTENSION[extension] ?? null);
}

/** Returns true for YouTube URLs. */
export function isYouTubeHost(hostname: string): boolean {
  const host = hostname.toLowerCase();
  return host === "youtu.be" || host.endsWith(".youtube.com") || host === "youtube.com";
}

/** Returns true for Vimeo URLs. */
export function isVimeoHost(hostname: string): boolean {
  const host = hostname.toLowerCase();
  return host === "vimeo.com" || host.endsWith(".vimeo.com");
}

function providerFor(kind: MediaKind, url: URL, extension: string | null): MediaProvider {
  if (kind === "image") {
    return "image";
  }

  if (kind === "embed") {
    if (isYouTubeHost(url.hostname)) {
      return "youtube";
    }

    if (isVimeoHost(url.hostname)) {
      return "vimeo";
    }

    return "generic-embed";
  }

  if (extension === "m3u8") {
    return "hls";
  }

  if (extension === "mpd") {
    return "dash";
  }

  return "native";
}

function isBlob(value: unknown): value is Blob {
  return typeof Blob !== "undefined" && value instanceof Blob;
}

function isMediaStream(value: unknown): value is MediaStream {
  return typeof MediaStream !== "undefined" && value instanceof MediaStream;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

type StructuredPlayerSource = Exclude<PlayerSource, ChunkedSource>;

function isStructuredSource(value: unknown): value is StructuredPlayerSource {
  return (
    isRecord(value) &&
    typeof value["src"] === "string" &&
    value["src"].length > 0 &&
    (value["kind"] === "video" ||
      value["kind"] === "audio" ||
      value["kind"] === "image" ||
      value["kind"] === "embed")
  );
}

function isChunkedSource(value: unknown): value is ChunkedSource {
  return (
    isRecord(value) &&
    "chunks" in value &&
    typeof value["type"] === "string" &&
    value["type"].length > 0 &&
    (value["kind"] === "video" || value["kind"] === "audio" || value["kind"] === "image")
  );
}

function chunkedSource(input: ChunkedSource): NormalizedSource {
  return Object.freeze({
    source: input,
    url: "",
    kind: input.kind,
    provider: input.kind === "image" ? "image" : "chunked",
    mimeType: input.type,
    extension: null,
    objectUrl: false,
    title: input.title ?? null,
    stream: null,
    chunks: input.chunks,
  });
}

function mimeTypeFromDataUrl(value: string): string | null {
  if (!value.startsWith("data:")) {
    return null;
  }

  const comma = value.indexOf(",");

  if (comma <= 5) {
    return null;
  }

  const header = value.slice(5, comma);
  const mime = header.split(";")[0]?.trim().toLowerCase() ?? "";
  return mime.length === 0 ? null : mime;
}

function structuredSource(
  input: StructuredPlayerSource,
  url: URL,
  extension: string | null,
): NormalizedSource {
  const mimeType = input.type ?? inferMimeType(extension);

  return Object.freeze({
    source: input,
    url: url.href,
    kind: input.kind,
    provider:
      input.kind === "embed"
        ? input.provider === "youtube"
          ? "youtube"
          : input.provider === "vimeo"
            ? "vimeo"
            : "generic-embed"
        : providerFor(input.kind, url, extension),
    mimeType,
    extension,
    objectUrl: false,
    title: input.kind === "embed" ? (input.title ?? null) : null,
    stream: null,
    chunks: null,
  });
}

/**
 * Normalizes any supported input into a URL plus engine decision.
 *
 * Object URLs created for `Blob`/`File` inputs are owned by the returned
 * descriptor and must be released with {@link revokeSource}.
 */
export function normalizeSource(input: PlayerSourceInput): NormalizedSource {
  if (Array.isArray(input)) {
    throw createPlayerError("A source list must be loaded through the player.", {
      code: "invalid-argument",
    });
  }

  if (isMediaStream(input)) {
    const source: PlayerSource = { kind: "video", src: "" };
    const normalized: NormalizedSource = {
      source,
      url: "",
      kind: "video",
      provider: "native",
      mimeType: null,
      extension: null,
      objectUrl: false,
      title: null,
      stream: input,
      chunks: null,
    };

    return Object.freeze(normalized);
  }

  if (isBlob(input)) {
    if (typeof URL === "undefined" || typeof URL.createObjectURL !== "function") {
      throw createPlayerError("Object URLs are not available in this environment.", {
        code: "unsupported-environment",
      });
    }

    const url = URL.createObjectURL(input);
    const type = typeof input.type === "string" && input.type.length > 0 ? input.type : null;
    const kind = detectMediaKind(null, type, new URL(url));
    const source: PlayerSource =
      kind === "image"
        ? { kind: "image", src: url, ...(type === null ? {} : { type }) }
        : kind === "audio"
          ? { kind: "audio", src: url, ...(type === null ? {} : { type }) }
          : { kind: "video", src: url, ...(type === null ? {} : { type }) };

    return Object.freeze({
      source,
      url,
      kind,
      provider: providerFor(kind, new URL(url), null),
      mimeType: type,
      extension: null,
      objectUrl: true,
      title: null,
      stream: null,
      chunks: null,
    });
  }

  if (isChunkedSource(input)) {
    return chunkedSource(input);
  }

  if (typeof input === "string") {
    if (input.trim().length === 0) {
      throw createPlayerError("The media source must not be empty.", {
        code: "invalid-argument",
      });
    }

    const url = toUrl(input);
    const extension = extensionOf(url.pathname);
    const mimeType = mimeTypeFromDataUrl(input) ?? inferMimeType(extension);
    const kind = detectMediaKind(extension, mimeType, url);
    const source: PlayerSource =
      kind === "embed"
        ? {
            kind: "embed",
            src: url.href,
            provider: isYouTubeHost(url.hostname)
              ? "youtube"
              : isVimeoHost(url.hostname)
                ? "vimeo"
                : "generic",
          }
        : kind === "image"
          ? { kind: "image", src: url.href }
          : kind === "audio"
            ? { kind: "audio", src: url.href }
            : { kind: "video", src: url.href };

    return Object.freeze({
      source,
      url: url.href,
      kind,
      provider: providerFor(kind, url, extension),
      mimeType,
      extension,
      objectUrl: false,
      title: null,
      stream: null,
      chunks: null,
    });
  }

  if (isStructuredSource(input)) {
    const url = toUrl(input.src);
    const extension = extensionOf(url.pathname);

    return structuredSource(input, url, extension);
  }

  throw createPlayerError("Unsupported media source.", {
    code: "invalid-argument",
    details: { value: typeof input },
  });
}

/** Returns a stable string token for change detection. */
export function sourceToken(input: PlayerSourceInput | null | undefined): string {
  if (input === null || input === undefined) {
    return "none";
  }

  if (Array.isArray(input)) {
    return `list:[${(input as readonly PlayerSourceInput[])
      .map((entry) => sourceToken(entry))
      .join(",")}]`;
  }

  if (typeof input === "string") {
    return `s:${input}`;
  }

  if (isBlob(input) || isMediaStream(input)) {
    let id = objectIds.get(input);

    if (id === undefined) {
      id = nextObjectId;
      nextObjectId += 1;
      objectIds.set(input, id);
    }

    return `${isBlob(input) ? "b" : "m"}:${id}`;
  }

  if (isChunkedSource(input)) {
    let id = objectIds.get(input);

    if (id === undefined) {
      id = nextObjectId;
      nextObjectId += 1;
      objectIds.set(input, id);
    }

    return `c:${id}:${input.type}`;
  }

  if (isStructuredSource(input)) {
    return `o:${input.kind}:${input.src}:${input.type ?? ""}`;
  }

  return "unknown";
}

/** Releases an object URL created by {@link normalizeSource}. */
export function revokeSource(source: NormalizedSource | null): void {
  if (source === null || !source.objectUrl) {
    return;
  }

  if (typeof URL !== "undefined" && typeof URL.revokeObjectURL === "function") {
    URL.revokeObjectURL(source.url);
  }
}
